  --border:                         oklch(0.893 0.0022 17.2); /* #DDDBDB */
  --border-strong:                  oklch(0.8203 0 0); /* #C4C4C4 */
  --input:                          oklch(0.893 0.0022 17.2); /* #DDDBDB */
