  --chart-3:                        oklch(0.5734 0.1335 241.05); /* #0180BF */
  --chart-4:                        oklch(0.4834 0.0074 75.35); /* #615E5A */
  --chart-5:                        oklch(0.391 0.0072 84.59); /* #474541 */
  --chart-mono-1:                   oklch(0.795 0.1473 73.78); /* #F4AC3D */
  --chart-mono-2:                   oklch(0.6853 0.1451 74.23); /* #CE8A00 */
  --chart-mono-3:                   oklch(0.583 0.1236 73.95); /* #A66E00 */
  --chart-mono-4:                   oklch(0.486 0.1028 74.43); /* #815500 */
