  --sidebar-accent:                 oklch(0.3012 0 0); /* #2E2E2E */
  --sidebar-accent-foreground:      oklch(0.9455 0.0027 106.45); /* #EDEDEB */
  --sidebar-border:                 oklch(0.3012 0 0); /* #2E2E2E */
  --sidebar-ring:                   oklch(0.795 0.1473 73.78); /* #F4AC3D */
